    .syntax unified
    .arm

GIC_DIST         = 0x08000000
GIC_CPU          = 0x08010000
GIC_CTLR         = 0x000
GICD_ISENABLER0  = 0x100
GICC_PMR         = 0x004
GICC_IAR         = 0x00c
GICC_EOIR        = 0x010
TIMER_INTID      = 30
TICKS_PER_SECOND = 100
SVC_MODE         = 0x13
IRQ_MODE         = 0x12

    .section .vectors, "ax"
    .balign 32
vectors:
    b       reset_handler
    b       unexpected_exception
    b       __tx_swi_interrupt
    b       unexpected_exception
    b       unexpected_exception
    b       unexpected_exception
    b       _tx_thread_context_save
    b       unexpected_exception

    .text
    .balign 4

/* Enter ThreadX with aligned SVC and IRQ stacks, vectors, and cleared BSS.  */
    .global reset_handler
    .type   reset_handler, %function
reset_handler:
    cpsid   if, #IRQ_MODE
    ldr     sp, =__irq_stack_end__
    cps     #SVC_MODE
    ldr     sp, =__stack_end__
    ldr     r0, =vectors
    mcr     p15, 0, r0, c12, c0, 0          @ VBAR
    isb
    ldr     r0, =__bss_start__
    ldr     r1, =__bss_end__
    mov     r2, #0
1:
    cmp     r0, r1
    strlo   r2, [r0], #4
    blo     1b
    bl      main

/* Report a failure from an exception mode with no C stack.  */
unexpected_exception:
    cpsid   if, #SVC_MODE
    b       harness_unexpected_exception

/* Enable the physical timer PPI on the single test core.  */
    .global _tx_initialize_low_level
    .type   _tx_initialize_low_level, %function
_tx_initialize_low_level:
    ldr     r0, =_tx_initialize_unused_memory
    ldr     r1, =__RAM_segment_used_end__
    str     r1, [r0]
    ldr     r0, =_tx_thread_system_stack_ptr
    ldr     r1, =__irq_stack_end__
    str     r1, [r0]

    ldr     r0, =GIC_DIST
    mov     r1, #(1 << TIMER_INTID)
    str     r1, [r0, #GICD_ISENABLER0]
    mov     r1, #1
    str     r1, [r0, #GIC_CTLR]
    ldr     r0, =GIC_CPU
    mov     r2, #0xff
    str     r2, [r0, #GICC_PMR]
    str     r1, [r0, #GIC_CTLR]
    mcr     p15, 0, r1, c14, c2, 1          @ CNTP_CTL
    b       reload_timer

/* Rearm the level-triggered timer before acknowledging end of interrupt.  */
    .global __tx_irq_processing_return
    .type   __tx_irq_processing_return, %function
__tx_irq_processing_return:
    push    {r4, r5}
    ldr     r5, =GIC_CPU
    ldr     r4, [r5, #GICC_IAR]
    ubfx    r0, r4, #0, #10
    cmp     r0, #TIMER_INTID
    bne     unexpected_exception
    bl      reload_timer
    dsb     sy
    str     r4, [r5, #GICC_EOIR]
    bl      _tx_timer_interrupt
    pop     {r4, r5}
    b       _tx_thread_context_restore

/* Set the next 100 Hz tick relative to the current timer count.  */
reload_timer:
    mrc     p15, 0, r0, c14, c0, 0          @ CNTFRQ
    mov     r1, #TICKS_PER_SECOND
    udiv    r0, r0, r1
    mcr     p15, 0, r0, c14, c2, 0          @ CNTP_TVAL
    isb
    bx      lr
